from __future__ import annotations

from pathlib import Path
from typing import Any


def stage_methods_page(settings: Any) -> Path:
    """Write the shared dashboard analysis and equations reference page."""

    page_root = Path(settings.output_root) / "learn-more"
    page_root.mkdir(parents=True, exist_ok=True)
    destination = page_root / "index.html"
    destination.write_text(METHODS_TEMPLATE, encoding="utf-8")
    return destination


